/* F.R.A.M.E. · YouTube Studio Assistant. No secrets belong in this file. */
(() => {
  'use strict';
  const KEY='frameflow-data-v1', CONFIG='frameflow-api-url-v1', AUTH_KEY='frameflow-session-v1', USER_KEY='frameflow-user-v1';
  const COLORS=['#a98bff','#70c8e8','#f2a76e','#f17986','#67c8a1','#e2ca65','#a8a3e8'];
  const DEFAULT={version:1,channels:[],categories:['Education','Entertainment','Gaming','Technology','Animation / Cartoon','Story','Social awareness','Other'],formats:['Long video','Shorts'],languages:['Tamil','English','Tamil + English','Other'],stages:['Content complete','Raw footage collected','Editing complete','YouTube upload complete'],projects:[],activity:[]};
  let currentUser=readUser(),data=load(),view='dashboard',activeFilter='All projects',selectedChannel='',editingProject=null,deleteTarget=null,mediaFilter='All files',mediaSort='Recent',mediaView='list',mediaProject='all',mediaChannel='all',selectedMediaId='';
  let mediaDbPromise=null,dataRevision=0;
  const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
  function readUser(){try{return JSON.parse(localStorage.getItem(USER_KEY)||'null')}catch{return null}}
  function storageKey(){return currentUser?KEY+':'+currentUser.id:KEY}
  function load(){try{return {...structuredClone(DEFAULT),...JSON.parse(localStorage.getItem(storageKey())||'{}')}}catch{return structuredClone(DEFAULT)}}
  function persist(){dataRevision++;localStorage.setItem(storageKey(),JSON.stringify(data));render()}
  function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
  function id(){return crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2)}
  function mediaDb(){if(mediaDbPromise)return mediaDbPromise;mediaDbPromise=new Promise((resolve,reject)=>{const request=indexedDB.open('frameflow-media-v1',1);request.onupgradeneeded=()=>request.result.createObjectStore('files',{keyPath:'key'});request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});return mediaDbPromise}
  async function storeLocalFile(key,file){const db=await mediaDb();return new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put({key,blob:file});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
  async function readLocalFile(key){const db=await mediaDb();return new Promise((resolve,reject)=>{const tx=db.transaction('files','readonly'),req=tx.objectStore('files').get(key);req.onsuccess=()=>resolve(req.result?.blob||null);req.onerror=()=>reject(req.error)})}
  async function removeLocalFile(key){if(!key)return;const db=await mediaDb();return new Promise(resolve=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').delete(key);tx.oncomplete=resolve;tx.onerror=resolve})}
  function time(){return new Date().toISOString()}
  function log(text,projectId=''){data.activity.unshift({id:id(),text,projectId,at:time()});data.activity=data.activity.slice(0,250)}
  function fmtDate(s,opts={month:'short',day:'numeric'}){return new Date(s).toLocaleDateString(undefined,opts)}
  function toast(msg){let el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),2400)}
  function progress(p){return p.tasks?.length?Math.round(p.tasks.filter(t=>t.done).length/p.tasks.length*100):0}
  function status(p){return progress(p)===100&&p.tasks.length?'Complete':p.tasks.some(t=>t.done)?'In progress':'Planning'}
  function channelName(id){return data.channels.find(c=>c.id===id)?.name||'Unassigned'}
  function escapeAttr(s=''){return esc(s).replace(/`/g,'&#96;')}
  async function api(action,payload={},quiet=false){const url=localStorage.getItem(CONFIG);if(!url)return null;const publicActions=['setupStatus','bootstrapAdmin','login'];if(!publicActions.includes(action)){const token=localStorage.getItem(AUTH_KEY);if(!token)return null;payload={...payload,sessionToken:token}}const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),10000);try{const r=await fetch(url,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action,payload}),redirect:'follow',signal:controller.signal});const j=await r.json();if(!j.ok)throw Error(j.error||'Request failed');return j.data}catch(e){if(/session expired|please sign in|account is disabled/i.test(e.message)){localStorage.removeItem(AUTH_KEY);localStorage.removeItem(USER_KEY);currentUser=null;render()}if(!quiet)toast(e.name==='AbortError'?'Cloud request timed out. Check the connection in Settings.':'Cloud request failed: '+e.message);return null}finally{clearTimeout(timer)}}  async function syncUp(action,payload){const result=await api(action,payload);return result}
function setView(next){view=next;selectedChannel='';$('#sidebar').classList.remove('open');document.body.classList.remove('menu-open');render()}
  function render(){
    $('#today').textContent=new Date().toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'});
    const cloud=!!localStorage.getItem(CONFIG),signedIn=!!localStorage.getItem(AUTH_KEY);$('#connection-state').textContent=cloud?(signedIn?'Account connected':'Sign in required'):'Local workspace';$('#connection-note').textContent=cloud?(currentUser?.username||'Secure cloud sync'):'Only on this browser';$('.connection-indicator').style.background=cloud&&signedIn?'var(--green)':'var(--orange)';if(currentUser){$('.profile b').textContent=currentUser.username;$('.profile small').textContent=currentUser.role==='admin'?'Administrator':'Studio member'}
    $('#nav-count').textContent=data.projects.length;$('#media-count').textContent=data.projects.reduce((n,p)=>n+(p.assets||[]).length,0);
    $$('.nav-link[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
    const current=view==='detail'?'Project workspace':view==='media'?'Media library':view[0].toUpperCase()+view.slice(1);$('#crumb').textContent=selectedChannel?channelName(selectedChannel):current;
    const root=$('#content');if(localStorage.getItem(CONFIG)&&!localStorage.getItem(AUTH_KEY)){root.innerHTML=authPage();$('#crumb').textContent='Sign in';bindAuth();return}renderChannels();
    if(view==='dashboard')root.innerHTML=dashboard();else if(view==='projects')root.innerHTML=projectsPage();else if(view==='media')root.innerHTML=mediaPage();else if(view==='activity')root.innerHTML=activityPage();else if(view==='settings')root.innerHTML=settingsPage();else if(view==='detail')root.innerHTML=detailPage(editingProject);
    bindContent();
  }
  function renderChannels(){const box=$('#channel-list');box.innerHTML=data.channels.filter(c=>c.enabled!==false).map((c,i)=>`<button class="channel-item ${selectedChannel===c.id?'selected':''}" data-channel="${esc(c.id)}"><i class="channel-dot" style="background:${COLORS[i%COLORS.length]}"></i>${esc(c.name)}<span class="channel-project-count">${data.projects.filter(p=>p.channelId===c.id).length}</span></button>`).join('')||'<div style="padding:8px 11px;color:#777987;font-size:10px">Add your first channel in Settings</div>'}
  function stat(label,note,num,icon,color){return `<div class="stat-card"><div class="stat-top">${label}<span class="stat-icon" style="color:${color};background:${color}18">${icon}</span></div><div class="stat-num">${num}</div><div class="stat-foot">${note}</div></div>`}
  function projectRow(p){let pct=progress(p),st=status(p);return `<div class="project-row" data-open="${esc(p.id)}"><div class="project-thumb" style="background:${p.format==='Shorts'?'#25372f':'#302947'};color:${p.format==='Shorts'?'#70d4b0':'#baa6ff'}">${p.format==='Shorts'?'▯':'▣'}</div><div><div class="project-title">${esc(p.name)}</div><div class="project-sub">${esc(channelName(p.channelId))} · ${fmtDate(p.createdAt)}</div></div><span class="format-pill ${p.format==='Shorts'?'format-short':'format-long'}">${esc(p.format)}</span><div class="project-progress"><span class="status-pill ${st==='Complete'?'status-complete':st==='In progress'?'status-progress':'status-planning'}">${st}</span><div class="row-progress"><i style="width:${pct}%"></i></div><div class="row-progress-text">${pct}% complete</div></div><div class="project-channel"><span class="project-sub">${esc(p.category||'Uncategorized')}</span></div><span class="row-arrow">›</span></div>`}
  function dashboard(){let ps=data.projects,active=ps.filter(p=>status(p)!=='Complete').length,done=ps.filter(p=>status(p)==='Complete').length,shorts=ps.filter(p=>p.format==='Shorts').length;
    return `<div class="page-heading"><div><div class="eyebrow">YOUR CREATIVE WORKSPACE</div><h1>Make room for the next big idea.</h1><p>One calm place to plan, create and publish across your channels.</p></div><button class="button button-primary" data-new><span>＋</span> Create project</button></div><div class="stats-grid">${stat('Total projects','Across all your channels',ps.length,'▤','var(--purple)')}${stat('In progress','Ready for your next step',active,'◷','var(--orange)')}${stat('Shorts projects','Vertical, quick stories',shorts,'▯','var(--green)')}${stat('Completed','Published or wrapped up',done,'✓','var(--blue)')}</div><div class="layout-grid"><section class="panel"><div class="panel-header"><div><h2>Recent projects</h2><small>Your latest creative work</small></div><button class="text-button" data-view="projects">View all →</button></div><div class="project-list">${ps.length?ps.slice().sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).slice(0,6).map(projectRow).join(''):`<div class="empty-state"><div class="empty-icon">✳</div><b>Your first story starts here.</b><p>Create a project to bring all your video details, tasks and assets together.</p><button class="button button-primary" data-new>＋ Create your first project</button></div>`}</div></section><div style="display:grid;align-content:start;gap:15px"><section class="panel"><div class="panel-header"><h2>Studio shortcuts</h2><small>Make progress</small></div><div class="quick-list"><div class="quick-item" data-view="projects"><span class="quick-icon" style="background:#302947;color:#baa6ff">▤</span><div><b>All projects</b><small>${ps.length} video ideas in your library</small></div><span class="quick-arrow">→</span></div><div class="quick-item" data-view="settings"><span class="quick-icon" style="background:#20372f;color:#75d5ae">◎</span><div><b>Manage channels</b><small>${data.channels.length} channels set up</small></div><span class="quick-arrow">→</span></div><div class="quick-item" data-view="settings"><span class="quick-icon" style="background:#3b3025;color:#f0b476">⚙</span><div><b>Workflow settings</b><small>Make the stages your own</small></div><span class="quick-arrow">→</span></div></div></section><section class="panel"><div class="panel-header"><h2>Workflow at a glance</h2><small>Across all projects</small></div><div class="workflow">${(data.stages||[]).map((s,i)=>{let total=ps.length,completed=ps.filter(p=>p.tasks?.[i]?.done).length;return `<div class="workflow-top"><b>${esc(s)}</b><span class="muted">${completed} / ${total}</span></div><div class="workflow-bar">${ps.length?ps.map(p=>`<i class="${p.tasks?.[i]?.done?'done':''}"></i>`).join(''):'<i></i><i></i><i></i>'}</div>`}).join('')||'<span class="muted">Add workflow stages in Settings.</span>'}</div></section></div></div>`}
  function projectsPage(){let ps=data.projects.filter(p=>!selectedChannel||p.channelId===selectedChannel);if(activeFilter==='Long video')ps=ps.filter(p=>p.format==='Long video');if(activeFilter==='Shorts')ps=ps.filter(p=>p.format==='Shorts');if(activeFilter==='In progress')ps=ps.filter(p=>status(p)==='In progress');if(activeFilter==='Complete')ps=ps.filter(p=>status(p)==='Complete');return `<div class="page-heading"><div><div class="eyebrow">YOUR VIDEO LIBRARY</div><h1>${selectedChannel?esc(channelName(selectedChannel)):'All projects'}</h1><p>Every idea, asset and next step — all in one place.</p></div><button class="button button-primary" data-new>＋ New project</button></div><div class="filter-row">${['All projects','Long video','Shorts','In progress','Complete'].map(x=>`<button class="filter-chip ${activeFilter===x?'active':''}" data-filter="${x}">${x}</button>`).join('')}</div>${ps.length?`<div class="project-grid">${ps.slice().sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).map(p=>{let pct=progress(p),st=status(p);return `<article class="project-card" data-open="${esc(p.id)}"><div class="project-card-top"><span class="format-pill ${p.format==='Shorts'?'format-short':'format-long'}">${esc(p.format)}</span><span class="status-pill ${st==='Complete'?'status-complete':st==='In progress'?'status-progress':'status-planning'}">${st}</span></div><h3>${esc(p.name)}</h3><div class="project-sub">${esc(channelName(p.channelId))} · ${fmtDate(p.createdAt)}</div><div class="card-meta"><span class="project-sub">${esc(p.category||'Uncategorized')}</span>${p.language?`<span class="project-sub">· ${esc(p.language)}</span>`:''}</div><div class="card-progress"><div class="row-progress"><i style="width:${pct}%"></i></div><div class="card-foot"><span>${pct}% complete</span><span>${p.tasks.filter(t=>t.done).length}/${p.tasks.length} stages</span></div></div></article>`}).join('')}</div>`:`<section class="panel"><div class="empty-state"><div class="empty-icon">✳</div><b>No projects in this view yet.</b><p>Create a project and keep your production moving.</p><button class="button button-primary" data-new>＋ Create project</button></div></section>`}`}
  function assetType(a){const mime=(a.type||'').toLowerCase();if(mime.startsWith('image/'))return 'Images';if(mime.startsWith('video/'))return 'Video';if(mime.startsWith('audio/'))return 'Audio';const ext=(a.name||'').split('.').pop().toLowerCase();if(['png','jpg','jpeg','gif','webp','svg','avif'].includes(ext))return 'Images';if(['mp4','mov','webm','m4v','mkv'].includes(ext))return 'Video';if(['mp3','wav','m4a','aac','ogg','flac'].includes(ext))return 'Audio';return 'Documents'}
  function allMedia(){return data.projects.flatMap(p=>(p.assets||[]).map(a=>({...a,createdAt:a.createdAt||p.updatedAt||p.createdAt,projectId:p.id,projectName:p.name,channel:channelName(p.channelId)}))).sort((a,b)=>(b.createdAt||'').localeCompare(a.createdAt||''))}
  function mediaPage(){let files=allMedia();if(mediaFilter!=='All files')files=files.filter(a=>assetType(a)===mediaFilter);if(mediaProject!=='all')files=files.filter(a=>a.projectId===mediaProject);if(mediaChannel!=='all')files=files.filter(a=>data.projects.find(p=>p.id===a.projectId)?.channelId===mediaChannel);const sorters={'Recent':(a,b)=>new Date(b.createdAt)-new Date(a.createdAt),'Oldest':(a,b)=>new Date(a.createdAt)-new Date(b.createdAt),'Name A–Z':(a,b)=>a.name.localeCompare(b.name),'Name Z–A':(a,b)=>b.name.localeCompare(a.name),'Largest first':(a,b)=>(b.size||0)-(a.size||0),'Smallest first':(a,b)=>(a.size||0)-(b.size||0)};files.sort(sorters[mediaSort]||sorters.Recent);if(!files.some(a=>String(a.id)===String(selectedMediaId)))selectedMediaId=files[0]?.id||'';const selected=files.find(a=>String(a.id)===String(selectedMediaId));const typeTabs=['All files','Images','Video','Audio','Documents'];return `<div class="page-heading"><div><div class="eyebrow">YOUR STUDIO FILES</div><h1>Media library</h1><p>All your project files, organized in one place.</p></div><span class="media-total">${files.length} FILE${files.length===1?'':'S'}</span></div><div class="media-manager-toolbar"><div class="media-search">⌕ <input id="media-search" placeholder="Search this library…" aria-label="Search media"></div><select id="media-project-filter" aria-label="Filter by project"><option value="all">All projects</option>${data.projects.map(p=>`<option value="${esc(p.id)}" ${mediaProject===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><select id="media-channel-filter" aria-label="Filter by channel"><option value="all">All channels</option>${data.channels.map(c=>`<option value="${esc(c.id)}" ${mediaChannel===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><select id="media-sort" aria-label="Sort files">${['Recent','Oldest','Name A–Z','Name Z–A','Largest first','Smallest first'].map(x=>`<option ${mediaSort===x?'selected':''}>${x}</option>`).join('')}</select><div class="media-view-toggle"><button data-media-view="list" class="${mediaView==='list'?'active':''}" title="List view">☷</button><button data-media-view="grid" class="${mediaView==='grid'?'active':''}" title="Grid view">▦</button></div></div><div class="filter-row media-type-tabs">${typeTabs.map(x=>`<button class="filter-chip ${mediaFilter===x?'active':''}" data-media-filter="${x}">${x}</button>`).join('')}</div>${files.length?`<div class="media-manager-layout ${mediaView==='grid'?'grid-mode':''}"><section class="media-file-browser"><div class="media-table-head"><span>Name</span><span>Project</span><span>Type</span><span>Date modified</span><span>Size</span></div><div class="media-table-body">${files.map(a=>`<div class="media-table-row ${String(a.id)===String(selectedMediaId)?'selected':''}" data-select-media="${esc(a.id)}" data-media-card data-name="${escapeAttr((a.name+' '+a.projectName+' '+a.channel).toLowerCase())}" tabindex="0"><span class="media-name-cell"><i class="file-type-icon ${assetType(a).toLowerCase()}">${fileIcon(a.name)}</i><b title="${escapeAttr(a.name)}">${esc(a.name)}</b><button class="media-row-preview" data-preview-media="${esc(a.id)}" title="Preview">▶</button></span><span class="media-project-cell" title="${escapeAttr(a.projectName)}">${esc(a.projectName)}</span><span class="media-type-cell">${assetType(a)}</span><span class="media-date-cell">${fmtDate(a.createdAt,{month:'short',day:'numeric',year:'numeric'})}</span><span class="media-size-cell">${sizeLabel(a.size||0)}</span></div>`).join('')}</div></section><aside class="media-details"><div class="media-details-title">Details</div>${selected?`<div class="media-detail-icon ${assetType(selected).toLowerCase()}">${fileIcon(selected.name)}</div><h2 title="${escapeAttr(selected.name)}">${esc(selected.name)}</h2><div class="media-detail-type">${assetType(selected)} · ${sizeLabel(selected.size||0)}</div><div class="media-detail-fields"><div><small>PROJECT</small><b>${esc(selected.projectName)}</b></div><div><small>CHANNEL</small><b>${esc(selected.channel)}</b></div><div><small>DATE ADDED</small><b>${fmtDate(selected.createdAt,{month:'long',day:'numeric',year:'numeric'})}</b></div><div><small>STORAGE</small><b>${selected.fileKey?'This browser':'Google Drive'}</b></div></div><button class="button button-primary media-detail-preview" data-preview-media="${esc(selected.id)}">▶ Preview / play</button>${selected.url?`<a class="button button-quiet media-drive-link" href="${safeDriveUrl(selected.url)}" target="_blank" rel="noopener">Open in Drive ↗</a>`:''}<button class="copy-btn media-project-link" data-open="${esc(selected.projectId)}">Open project</button>`:`<div class="media-details-empty">Select a file to see details.</div>`}</aside></div>`:`<section class="panel"><div class="empty-state"><div class="empty-icon">▧</div><b>${allMedia().length?'No files match these filters.':'Your media library is ready.'}</b><p>${allMedia().length?'Change a filter to see more files.':'Upload files from a project. They will appear here with details and preview options.'}</p>${allMedia().length?'':'<button class="button button-quiet" data-view="projects">Browse projects →</button>'}</div></section>`}`}  function safeDriveUrl(value){try{const u=new URL(value);return u.protocol==='https:'&&u.hostname==='drive.google.com'?esc(u.href):'#'}catch{return '#'}}
  function findMedia(assetId){for(const p of data.projects){const a=(p.assets||[]).find(x=>String(x.id)===String(assetId));if(a)return {project:p,asset:a}}return null}
  async function previewMedia(assetId){const found=findMedia(assetId);if(!found)return;const {project,asset}=found,kind=assetType(asset);$('#media-modal-title').textContent=asset.name;$('#media-modal-meta').innerHTML=`${esc(project.name)} · ${esc(kind)} · ${sizeLabel(asset.size||0)}`;const viewer=$('#media-viewer');viewer.innerHTML='<div class="media-loading">Preparing preview…</div>';$('#media-dialog').showModal();if(asset.fileKey){try{const blob=await readLocalFile(asset.fileKey);if(!blob)throw Error('This local file is no longer available.');const url=URL.createObjectURL(blob);viewer.dataset.objectUrl=url;if(kind==='Images')viewer.innerHTML=`<img class="media-image-preview" src="${url}" alt="${escapeAttr(asset.name)}">`;else if(kind==='Video')viewer.innerHTML=`<video class="media-video-preview" src="${url}" controls playsinline></video>`;else if(kind==='Audio')viewer.innerHTML=`<audio class="media-audio-preview" src="${url}" controls></audio>`;else viewer.innerHTML=`<div class="media-document-preview">${fileIcon(asset.name)}<p>${esc(asset.name)}</p><a class="button button-primary" href="${url}" download="${escapeAttr(asset.name)}">Download file</a></div>`}catch(e){viewer.innerHTML=`<div class="media-loading">${esc(e.message)}</div>`}}else if(asset.id&&asset.url){viewer.innerHTML=`<iframe class="drive-preview" src="https://drive.google.com/file/d/${encodeURIComponent(asset.id)}/preview" allow="autoplay; encrypted-media" allowfullscreen title="${escapeAttr(asset.name)}"></iframe><a class="copy-btn media-open-drive" href="${safeDriveUrl(asset.url)}" target="_blank" rel="noopener">Open in Google Drive ↗</a>`}else viewer.innerHTML=`<div class="media-document-preview">${fileIcon(asset.name)}<p>${esc(asset.name)}</p><span>Preview unavailable</span></div>`}
  function mediaPageSearch(){const input=$('#media-search');if(!input)return;input.addEventListener('input',()=>{const q=input.value.toLowerCase().trim();$$('[data-media-card]').forEach(c=>c.hidden=!c.dataset.name.includes(q))})}
  function activityPage(){return `<div class="page-heading"><div><div class="eyebrow">YOUR STUDIO TIMELINE</div><h1>Activity</h1><p>A little history of everything moving forward.</p></div></div><section class="panel">${data.activity.length?`<div class="activity-list">${data.activity.map(a=>`<div class="activity-row"><span class="activity-mark">◷</span><div><b>${esc(a.text)}</b><small>${fmtDate(a.at,{month:'short',day:'numeric',year:'numeric'})} · ${new Date(a.at).toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'})}</small></div></div>`).join('')}</div>`:`<div class="empty-state"><div class="empty-icon">◷</div><b>Your timeline will grow with your studio.</b><p>Project creation and workflow updates show up here.</p></div>`}</section>`}
  function titleOptionsFor(p){return Array.isArray(p.titleOptions)&&p.titleOptions.length===3?p.titleOptions:[p.title||'','','']}
  function scriptsFor(p){if(Array.isArray(p.scriptDrafts)&&p.scriptDrafts.length)return p.scriptDrafts;if(p.story)return [{id:'legacy-script',name:'Script 1',content:p.story}];return [{id:'script-'+p.id,name:'Script 1',content:''}]}
  function detailPage(p){if(!p)return '<div class="empty-state">Project unavailable. <button class="button button-quiet" data-view="projects">Back to projects</button></div>';const pct=progress(p),titles=titleOptionsFor(p),scripts=scriptsFor(p);return `<div class="detail-head"><button class="icon-btn back-button" data-view="projects">←</button><div class="detail-title"><div class="eyebrow">PROJECT WORKSPACE · ${esc(p.format.toUpperCase())}</div><h1>${esc(p.name)}</h1><p>Created ${fmtDate(p.createdAt,{month:'long',day:'numeric',year:'numeric'})} · ${esc(channelName(p.channelId))}</p></div><button class="button button-quiet" data-copy>↗ Copy details</button></div><div class="detail-columns"><div><section class="panel detail-panel"><div class="title-copy"><div><h2>Video details</h2><p class="subhead">Try three title options, then choose your winner.</p></div><button class="copy-btn" data-save-project-details>Save edits</button></div><div class="title-options">${titles.map((title,i)=>`<label class="title-option"><span>OPTION ${String.fromCharCode(65+i)}</span><input data-title-option="${i}" value="${escapeAttr(title)}" maxlength="120" placeholder="Enter title option ${String.fromCharCode(65+i)}"><button type="button" class="copy-btn" data-copy-title="${i}" title="Copy title">Copy</button></label>`).join('')}</div><label class="meta-label">DESCRIPTION</label><div class="copy-field"><textarea class="detail-edit" name="description" rows="4" placeholder="Add your video description">${esc(p.description||'')}</textarea><button type="button" class="copy-btn" data-copy-description>Copy</button></div><div class="metadata-grid project-meta"><div><span class="meta-label">CATEGORY</span><div class="meta-value">${esc(p.category||'—')}</div></div><div><span class="meta-label">LANGUAGE</span><div class="meta-value">${esc(p.language||'—')}</div></div></div></section><section class="panel detail-panel"><div class="script-heading"><div><h2>Script drafts</h2><p class="subhead">Keep alternate scripts separate and copy any version in one click.</p></div><button class="button button-quiet" data-add-script>＋ New script</button></div><div class="script-drafts">${scripts.map((s,i)=>`<article class="script-draft"><div class="script-draft-head"><label><span class="meta-label">SCRIPT ${i+1} NAME</span><input class="script-name" data-script-name="${esc(s.id)}" value="${escapeAttr(s.name||`Script ${i+1}`)}" maxlength="60"></label><div class="script-actions"><button type="button" class="copy-btn" data-copy-script="${esc(s.id)}">Copy script</button><button type="button" class="copy-btn" data-save-script="${esc(s.id)}">Save</button>${scripts.length>1?`<button type="button" class="asset-remove" data-delete-script="${esc(s.id)}" title="Remove script">×</button>`:''}</div></div><textarea class="script-content" data-script-content="${esc(s.id)}" rows="8" placeholder="Write this version of the script here…">${esc(s.content||'')}</textarea></article>`).join('')}</div></section><section class="panel detail-panel"><h2>Production stages</h2><p class="subhead">A clear next step at every stage · ${pct}% complete</p>${p.tasks.map((t,i)=>`<div class="task-row ${t.done?'done':''}"><input type="checkbox" class="task-check" data-task="${i}" ${t.done?'checked':''}><span class="task-name">${esc(t.name)}</span><button class="task-edit" data-task-edit="${i}" title="Rename stage">···</button></div>`).join('')||'<span class="muted">Add workflow stages in Settings.</span>'}</section></div><div><section class="panel detail-panel asset-panel"><div class="asset-heading"><div><h2>Raw assets</h2><p class="subhead">Keep footage, images, audio and references together.</p></div><span class="asset-count">${(p.assets||[]).length} FILES</span></div><div class="asset-drop"><input id="asset-input" type="file" multiple hidden style="display:none!important"><div class="asset-drop-zone"><div class="asset-upload-icon">↥</div><strong>Drop your files here</strong><span>or choose from your device</span><button type="button" class="button button-quiet asset-choose" data-pick-assets>Choose files</button><small>Up to ${maxFileLabel()} per file · saved to this project’s Drive folder when connected</small></div></div><div class="asset-list">${(p.assets||[]).map((a,i)=>`<div class="asset-row"><span>${fileIcon(a.name)}</span><span title="${escapeAttr(a.name)}">${esc(a.name)}</span><small>${sizeLabel(a.size)}</small><button class="copy-btn" data-preview-media="${esc(a.id)}">▶</button><button class="asset-remove" data-remove-asset="${i}" title="Remove">×</button></div>`).join('')||'<div class="muted" style="padding:12px 0">No assets added yet.</div>'}</div></section><section class="panel detail-panel"><h2>Progress</h2><div style="font:700 26px Manrope">${pct}<span style="font-size:14px;color:#91929f">%</span></div><div class="row-progress" style="height:6px;margin-top:9px"><i style="width:${pct}%"></i></div><div class="workflow-legend"><span>${p.tasks.filter(t=>t.done).length} stages complete</span><span>${p.tasks.length} total</span></div></section><section class="panel detail-panel"><h2>Project actions</h2><button class="button button-quiet" style="width:100%;justify-content:center" data-delete-project>Delete project</button></section></div></div>`}  function authPage(){return `<div class="auth-shell"><section class="panel auth-card"><div class="brand auth-brand"><span class="brand-mark">▶</span><span>F.R.A.M.E.<small>VIDEO STUDIO ASSISTANT</small></span></div><div class="eyebrow">YOUR PRIVATE WORKSPACE</div><h1>Welcome back.</h1><p class="auth-copy">Sign in with the account created by your administrator. Your projects sync across your devices.</p><form id="login-form" class="auth-form"><label>User ID<input name="username" autocomplete="username" required minlength="3" placeholder="Your user ID"></label><label>Password<input name="password" type="password" autocomplete="current-password" required placeholder="Your password"></label><button class="button button-primary" type="submit">Sign in <span>→</span></button></form><div class="auth-divider"><span>FIRST TIME SETUP</span></div><button class="copy-btn" id="setup-admin-trigger" hidden>Set up the first administrator</button><form id="setup-admin-form" class="auth-form" hidden><p class="notice">Run <b>initializeBootstrapKey</b> once in your Apps Script editor and paste the one-time key shown in the execution log. This creates the only administrator account.</p><label>One-time setup key<input name="bootstrapKey" autocomplete="off" required></label><label>Admin user ID<input name="username" autocomplete="username" required minlength="3"></label><label>Admin password<input name="password" type="password" autocomplete="new-password" required minlength="12"></label><button class="button button-primary" type="submit">Create admin account</button></form><details class="auth-connection"><summary>Change Apps Script address</summary><form id="auth-url-form"><input name="url" type="url" placeholder="Apps Script web app URL" value="${escapeAttr(localStorage.getItem(CONFIG)||'')}"><button class="button button-quiet">Save address</button></form></details><p class="auth-foot">Account access is managed by your studio administrator.</p></section></div>`}
  function bindAuth(){
    $('#auth-url-form')?.addEventListener('submit',e=>{e.preventDefault();const url=new FormData(e.currentTarget).get('url').trim();if(!url.startsWith('https://script.google.com/macros/s/'))return toast('Enter a valid Apps Script web app URL');localStorage.setItem(CONFIG,url);toast('Apps Script address saved');render()});
    $('#setup-admin-trigger')?.addEventListener('click',()=>{$('#setup-admin-form').hidden=false;$('#setup-admin-trigger').hidden=true});
    $('#login-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget),result=await api('login',{username:f.get('username'),password:f.get('password')});if(result?.token)await acceptSession(result)});
    $('#setup-admin-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget),result=await api('bootstrapAdmin',{bootstrapKey:f.get('bootstrapKey'),username:f.get('username'),password:f.get('password')});if(result?.token)await acceptSession(result)});
    api('setupStatus',{},true).then(s=>{if(s?.needsAdmin&&$('#setup-admin-trigger'))$('#setup-admin-trigger').hidden=false});
  }
  async function acceptSession(result){const legacy=JSON.parse(localStorage.getItem(KEY)||'null');localStorage.setItem(AUTH_KEY,result.token);localStorage.setItem(USER_KEY,JSON.stringify(result.user));currentUser=result.user;data=load();dataRevision=0;render();await syncAccountData(legacy)}
  async function syncAccountData(legacyData){const rev=dataRevision;let settings=await api('getSettings',{},true),remote=await api('listProjects',{},true);if(!settings||!Array.isArray(remote)||rev!==dataRevision)return;if(!remote.length&&currentUser?.role==='admin'&&legacyData?.projects?.length){const importSettings={channels:legacyData.channels||[],categories:legacyData.categories||DEFAULT.categories,formats:legacyData.formats||DEFAULT.formats,languages:legacyData.languages||DEFAULT.languages,stages:legacyData.stages||DEFAULT.stages};await api('importBackup',{projects:legacyData.projects,settings:importSettings},true);settings=await api('getSettings',{},true);remote=await api('listProjects',{},true)}if(Array.isArray(remote)&&rev===dataRevision){data={...data,...settings,projects:remote};localStorage.setItem(storageKey(),JSON.stringify(data));render()}}
  function accountPanel(){if(!currentUser)return '';if(currentUser.role!=='admin')return `<section class="panel settings-panel"><h2>Your account</h2><p>Signed in as <b>${esc(currentUser.username)}</b>. Your work is private to this account.</p><form id="change-password-form" class="account-form"><label>Current password<input name="currentPassword" type="password" autocomplete="current-password" required></label><label>New password (12+ characters)<input name="newPassword" type="password" autocomplete="new-password" minlength="12" required></label><button class="button button-quiet">Change password</button><button type="button" class="button button-quiet" data-logout>Sign out</button></form></section>`;return `<section class="panel settings-panel"><h2>Admin · user accounts</h2><p>Create user IDs and passwords. Each user gets a separate workspace and Drive folder.</p><form id="create-user-form" class="account-form"><label>User ID<input name="username" required minlength="3" maxlength="40" pattern="[A-Za-z0-9._-]+" placeholder="e.g. editor01"></label><label>Initial password<input name="password" type="password" required minlength="12" placeholder="At least 12 characters"></label><button class="button button-primary">＋ Create user</button></form><div id="user-list" class="user-list"><span class="muted">Loading accounts…</span></div><button type="button" class="button button-quiet" data-logout>Sign out</button></section>`}
  async function refreshUsers(){const box=$('#user-list');if(!box)return;const users=await api('adminListUsers',{},true);if(!Array.isArray(users)){box.innerHTML='<span class="muted">Could not load accounts.</span>';return}box.innerHTML=users.map(u=>`<div class="user-row"><div><b>${esc(u.username)}</b><small>${u.role==='admin'?'Administrator':'User'} · ${u.enabled?'Enabled':'Disabled'}</small></div>${u.role==='admin'?'<span class="user-badge">ADMIN</span>':`<button class="copy-btn" data-user-toggle="${esc(u.id)}" data-enabled="${u.enabled}">${u.enabled?'Disable':'Enable'}</button><button class="copy-btn" data-user-reset="${esc(u.id)}">Reset password</button>`}</div>`).join('')||'<span class="muted">No accounts yet.</span>';$$('[data-user-toggle]').forEach(b=>b.addEventListener('click',async()=>{await api('adminSetEnabled',{userId:b.dataset.userToggle,enabled:b.dataset.enabled!=='true'});refreshUsers()}));$$('[data-user-reset]').forEach(b=>b.addEventListener('click',async()=>{const password=prompt('Enter the new password (at least 12 characters). Share it with the user securely.');if(password){const r=await api('adminResetPassword',{userId:b.dataset.userReset,password});if(r)toast('Password updated')}}))}
  function settingList(key){return `<div class="setting-list">${(data[key]||[]).map((v,i)=>`<div class="setting-line"><span class="color-dot" style="background:${COLORS[i%COLORS.length]}"></span><b>${esc(v)}</b><div class="setting-actions"><button data-option-edit="${key}:${i}" title="Rename">✎</button><button data-option-delete="${key}:${i}" title="Delete">×</button></div></div>`).join('')}</div><form class="settings-add" data-add-option="${key}"><input name="value" required maxlength="60" placeholder="Add an option…"><button class="button button-quiet">＋ Add</button></form>`}
  function settingsPage(){return `<div class="page-heading"><div><div class="eyebrow">MAKE IT YOURS</div><h1>Studio settings</h1><p>Your channels, workflow and cloud connection in one place.</p></div></div><div class="settings-grid"><section class="panel settings-panel"><h2>YouTube channels</h2><p>Add as many channels as you manage. Projects stay organized by channel.</p>${data.channels.length?`<div class="setting-list">${data.channels.map((c,i)=>`<div class="setting-line channel-setting"><span class="color-dot" style="background:${COLORS[i%COLORS.length]}"></span><div><b>${esc(c.name)}</b><small>${esc(c.url||'No URL added')}</small></div><input type="checkbox" class="toggle" data-toggle-channel="${esc(c.id)}" ${c.enabled!==false?'checked':''} aria-label="Enable channel"><div class="setting-actions"><button data-edit-channel="${esc(c.id)}" title="Edit">✎</button><button data-delete-channel="${esc(c.id)}" title="Delete">×</button></div></div>`).join('')}</div>`:'<div class="empty-state" style="padding:22px 0"><b>No channels added yet.</b><p>Add your first channel to get started.</p></div>'}<button class="button button-quiet" style="margin-top:12px" data-add-channel>＋ Add channel</button></section><section class="panel settings-panel"><h2>Cloud connection</h2><p>Use this same Apps Script address on every computer, then sign in with your account.</p><div class="notice">Projects and settings are saved to your Google Sheet. Each account has its own Drive folder. Keep the deployment restricted to authenticated app accounts.</div><label class="meta-label">YOUR WEB APP URL</label><div class="integration-input"><input id="api-url" type="url" placeholder="https://script.google.com/macros/s/…/exec" value="${escapeAttr(localStorage.getItem(CONFIG)||'')}"><button class="button button-quiet" data-connect>Save</button></div><div style="display:flex;gap:8px;margin-top:9px"><button class="copy-btn" data-test-connection>Test connection</button><button class="copy-btn" data-sync>Sync this account</button></div><div class="guide-box">First setup and redeployment steps are in <a href="README.md">README.md</a>.</div></section><section class="panel settings-panel"><h2>Video formats</h2><p>Choose the formats you use when starting a project.</p>${settingList('formats')}</section><section class="panel settings-panel"><h2>Categories</h2><p>Keep your project topics consistent and searchable.</p>${settingList('categories')}</section><section class="panel settings-panel"><h2>Languages</h2><p>Languages your channel publishes in.</p>${settingList('languages')}</section><section class="panel settings-panel"><h2>Workflow stages</h2><p>These stages appear as a checklist on each project.</p>${settingList('stages')}</section><section class="panel settings-panel"><h2>Backup &amp; portability</h2><p>Save or move a metadata copy any time. Media files stay in Drive/browser storage.</p><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="button button-quiet" data-export>⇩ Download JSON backup</button><label class="button button-quiet" for="import-file">⇧ Import backup<input id="import-file" type="file" accept="application/json,.json" hidden></label></div></section>${accountPanel()}</div>`}  function maxFileLabel(){return '25 MB'}function sizeLabel(n){return n<1024*1024?Math.max(1,Math.round(n/1024))+' KB':(n/1024/1024).toFixed(1)+' MB'}function fileIcon(n){let ext=n.split('.').pop().toLowerCase();return ({png:'▧',jpg:'▧',jpeg:'▧',gif:'▧',mp4:'▷',mov:'▷',mp3:'♫',wav:'♫',pdf:'▤',txt:'▤'})[ext]||'↗'}
  function populateSelects(){const form=$('#project-form');if(!form)return;const fill=(sel,items,selected)=>{sel.innerHTML=items.map(x=>`<option ${x===selected?'selected':''}>${esc(x)}</option>`).join('')};fill($('#project-channel'),data.channels.filter(c=>c.enabled!==false).map(c=>c.name),data.channels.find(c=>c.id===selectedChannel)?.name);fill($('#project-format'),data.formats,data.formats[0]);fill($('#project-category'),data.categories,data.categories[0]);fill($('#project-language'),data.languages,data.languages[0]);}
  function bindContent(){
    $$('[data-view]').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));
$('#create-user-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget),r=await api('adminCreateUser',{username:f.get('username'),password:f.get('password')});if(r){e.currentTarget.reset();toast(`Created account ${r.username}`);refreshUsers()}});
    $('#change-password-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget),r=await api('changePassword',{currentPassword:f.get('currentPassword'),newPassword:f.get('newPassword')});if(r){e.currentTarget.reset();toast('Password changed')}});
    $$('[data-logout]').forEach(b=>b.addEventListener('click',signOut));
    if($('#user-list'))refreshUsers();
    $$('[data-new]').forEach(b=>b.addEventListener('click',openProjectModal));
    $$('[data-open]').forEach(el=>el.addEventListener('click',()=>{editingProject=data.projects.find(p=>p.id===el.dataset.open);if(editingProject){view='detail';render()}}));
    $$('[data-channel]').forEach(el=>el.addEventListener('click',()=>{selectedChannel=el.dataset.channel;activeFilter='All projects';view='projects';$('#sidebar').classList.remove('open');document.body.classList.remove('menu-open');render()}));
    $$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{activeFilter=b.dataset.filter;render()}));
$$('[data-media-filter]').forEach(b=>b.addEventListener('click',()=>{mediaFilter=b.dataset.mediaFilter;render()}));
    mediaPageSearch();
$('#media-project-filter')?.addEventListener('change',e=>{mediaProject=e.target.value;render()});
    $('#media-channel-filter')?.addEventListener('change',e=>{mediaChannel=e.target.value;render()});
    $('#media-sort')?.addEventListener('change',e=>{mediaSort=e.target.value;render()});
    $$('[data-media-view]').forEach(b=>b.addEventListener('click',()=>{mediaView=b.dataset.mediaView;render()}));
    $$('[data-select-media]').forEach(row=>row.addEventListener('click',e=>{if(e.target.closest('[data-preview-media]'))return;selectedMediaId=row.dataset.selectMedia;render()}));
    $$('[data-preview-media]').forEach(b=>b.addEventListener('click',()=>previewMedia(b.dataset.previewMedia)));
    $('#close-media')?.addEventListener('click',()=>$('#media-dialog').close());
    $('#media-dialog')?.addEventListener('close',()=>{const viewer=$('#media-viewer');if(viewer.dataset.objectUrl){URL.revokeObjectURL(viewer.dataset.objectUrl);delete viewer.dataset.objectUrl}viewer.innerHTML=''});
    $$('[data-remove-media]').forEach(b=>b.addEventListener('click',async()=>{const p=data.projects.find(x=>x.id===b.dataset.projectId);if(!p)return;const i=p.assets.findIndex(a=>String(a.id)===b.dataset.removeMedia);if(i<0)return;const [a]=p.assets.splice(i,1);await removeLocalFile(a.fileKey);log(`Removed ${a.name} from ${p.name}`,p.id);persist();syncUp('updateProject',p)}));
    $$('.quick-item').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));
    $('[data-save-project-details]')?.addEventListener('click',async()=>{editingProject.titleOptions=$$('[data-title-option]').map(x=>x.value);editingProject.title=editingProject.titleOptions.find(Boolean)||'';editingProject.description=$('[name="description"]')?.value||'';editingProject.updatedAt=time();persist();await syncUp('updateProject',editingProject);toast('Video details saved')});
    $$('[data-copy-title]').forEach(b=>b.addEventListener('click',()=>copyText($$('[data-title-option]')[+b.dataset.copyTitle]?.value||'')));
    $('[data-copy-description]')?.addEventListener('click',()=>copyText($('[name="description"]')?.value||''));
    $$('[data-copy-script]').forEach(b=>b.addEventListener('click',()=>copyText($(`[data-script-content="${CSS.escape(b.dataset.copyScript)}"]`)?.value||'')));
    $('[data-add-script]')?.addEventListener('click',()=>{editingProject.scriptDrafts=scriptsFor(editingProject);editingProject.scriptDrafts.push({id:id(),name:`Script ${editingProject.scriptDrafts.length+1}`,content:''});editingProject.updatedAt=time();persist();render()});
    $$('[data-save-script]').forEach(b=>b.addEventListener('click',async()=>{const draft=editingProject.scriptDrafts.find(x=>x.id===b.dataset.saveScript);if(!draft)return;draft.name=$(`[data-script-name="${CSS.escape(draft.id)}"]`).value.trim()||'Untitled script';draft.content=$(`[data-script-content="${CSS.escape(draft.id)}"]`).value;editingProject.updatedAt=time();persist();await syncUp('updateProject',editingProject);toast('Script saved')}));
    $$('[data-delete-script]').forEach(b=>b.addEventListener('click',()=>{if(editingProject.scriptDrafts.length<2)return;editingProject.scriptDrafts=editingProject.scriptDrafts.filter(x=>x.id!==b.dataset.deleteScript);editingProject.updatedAt=time();persist();syncUp('updateProject',editingProject);render()}));    $$('[data-task]').forEach(x=>x.addEventListener('change',async()=>{const i=+x.dataset.task,t=editingProject.tasks[i];t.done=x.checked;log(`${t.done?'Completed':'Reopened'} “${t.name}” in ${editingProject.name}`,editingProject.id);persist();await syncUp('updateProject',editingProject)}));
    $$('[data-save-details]').forEach(b=>b.addEventListener('click',async()=>{for(const el of $$('.detail-edit'))if(el.name)editingProject[el.name]=el.value;editingProject.updatedAt=time();log(`Updated details for ${editingProject.name}`,editingProject.id);persist();await syncUp('updateProject',editingProject);toast('Project details saved')}));
    $('[data-copy]')?.addEventListener('click',()=>{let p=editingProject;copyText(`Title: ${p.title||p.name}\n\nDescription:\n${p.description||''}`)});
    $$('[data-task-edit]').forEach(b=>b.addEventListener('click',()=>{let i=+b.dataset.taskEdit,v=prompt('Rename workflow stage',editingProject.tasks[i].name);if(v?.trim()){editingProject.tasks[i].name=v.trim();editingProject.updatedAt=time();persist();syncUp('updateProject',editingProject)}}));
    $('#asset-input')?.addEventListener('change',e=>addFiles(e.target.files));
    $('[data-pick-assets]')?.addEventListener('click',()=>$('#asset-input')?.click());
    $('.asset-drop')?.addEventListener('dragover',e=>{e.preventDefault();e.currentTarget.classList.add('drag')});$('.asset-drop')?.addEventListener('dragleave',e=>e.currentTarget.classList.remove('drag'));$('.asset-drop')?.addEventListener('drop',e=>{e.preventDefault();addFiles(e.dataTransfer.files)});
    $$('[data-remove-asset]').forEach(b=>b.addEventListener('click',async()=>{const [a]=editingProject.assets.splice(+b.dataset.removeAsset,1);await removeLocalFile(a?.fileKey);persist();syncUp('updateProject',editingProject)}));
    $('[data-delete-project]')?.addEventListener('click',()=>{if(confirm('Delete this project and its metadata? Assets already in Drive are not automatically deleted.')){const removedId=editingProject.id;data.projects=data.projects.filter(p=>p.id!==removedId);log(`Deleted project ${editingProject.name}`);editingProject=null;view='projects';persist();syncUp('deleteProject',{id:removedId})}});
    $$('[data-add-option]').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();let key=f.dataset.addOption,v=new FormData(f).get('value').trim();if(v&&!data[key].some(x=>x.toLowerCase()===v.toLowerCase())){data[key].push(v);log(`Added ${v} to ${key}`);persist();syncUp('saveSettings',data)}f.reset()}));
    $$('[data-option-delete]').forEach(b=>b.addEventListener('click',()=>{let [key,i]=b.dataset.optionDelete.split(':');if(confirm(`Remove “${data[key][i]}” from settings? Existing projects are unchanged.`)){data[key].splice(+i,1);persist();syncUp('saveSettings',data)}}));
    $$('[data-option-edit]').forEach(b=>b.addEventListener('click',()=>{let [key,i]=b.dataset.optionEdit.split(':');let v=prompt('Rename option',data[key][i]);if(v?.trim()){data[key][i]=v.trim();persist();syncUp('saveSettings',data)}}));
    $('[data-add-channel]')?.addEventListener('click',()=>editChannel());$$('[data-edit-channel]').forEach(b=>b.addEventListener('click',()=>editChannel(data.channels.find(c=>c.id===b.dataset.editChannel))));
    $$('[data-delete-channel]').forEach(b=>b.addEventListener('click',()=>{deleteTarget=b.dataset.deleteChannel;$('#confirm-dialog').showModal()}));
    $$('[data-toggle-channel]').forEach(b=>b.addEventListener('change',()=>{let c=data.channels.find(x=>x.id===b.dataset.toggleChannel);c.enabled=b.checked;log(`${b.checked?'Enabled':'Disabled'} channel ${c.name}`);persist();syncUp('saveSettings',data)}));
    $('[data-connect]')?.addEventListener('click',()=>{let url=$('#api-url').value.trim();if(url&&!url.startsWith('https://script.google.com/macros/s/'))return toast('Enter a valid Apps Script web app URL');localStorage.setItem(CONFIG,url);toast(url?'Connection URL saved':'Cloud connection removed');render()});
    $('[data-test-connection]')?.addEventListener('click',async()=>{let r=await api('ping');if(r)toast('Apps Script connection works')});
    $('[data-sync]')?.addEventListener('click',async()=>{const r=await api('importBackup',{...data,settings:{channels:data.channels,categories:data.categories,formats:data.formats,languages:data.languages,stages:data.stages}});if(r){toast('This account synced to Google Sheets');syncAccountData(null)}});
    $$('[data-export],#export-btn,#backup-top').forEach(b=>b?.addEventListener('click',exportBackup));
    $('#import-file')?.addEventListener('change',importBackup);
  }
  function openProjectModal(){if(!data.channels.some(c=>c.enabled!==false)){setView('settings');toast('Add a channel first, then create your project');return}populateSelects();$('#project-dialog').showModal()}
  function editChannel(channel){const f=$('#channel-form');f.reset();f.elements.id.value=channel?.id||'';f.elements.name.value=channel?.name||'';f.elements.url.value=channel?.url||'';$('#channel-dialog-title').textContent=channel?'Edit channel':'Add a channel';$('#channel-dialog').showModal()}
  async function addFiles(files){if(!editingProject)return;const project=editingProject,list=[...files];if(!list.length)return;const tooBig=list.filter(f=>f.size>25*1024*1024);if(tooBig.length)return toast('Files over 25 MB are not accepted by this browser uploader');try{const items=await Promise.all(list.map(async f=>{const assetId=id();if(localStorage.getItem(CONFIG)){const b64=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(String(r.result).split(',')[1]);r.onerror=rej;r.readAsDataURL(f)});const result=await api('uploadFile',{projectId:project.id,name:f.name,mimeType:f.type||'application/octet-stream',base64:b64});return result?{id:result.id,name:f.name,size:f.size,type:f.type||'',url:result.url,createdAt:time()}:null}const fileKey=id();await storeLocalFile(fileKey,f);return {id:assetId,name:f.name,size:f.size,type:f.type||'',fileKey,local:true,createdAt:time()}}));project.assets=[...(project.assets||[]),...items.filter(Boolean)];project.updatedAt=time();log(`Added ${items.filter(Boolean).length} asset(s) to ${project.name}`,project.id);persist();toast(localStorage.getItem(CONFIG)?'Assets uploaded to Google Drive':'Files saved in this browser and ready to preview')}catch(e){toast('Could not save file: '+e.message)}}  async function copyText(s){try{await navigator.clipboard.writeText(s);toast('Copied to clipboard')}catch{prompt('Copy project details',s)}}
  async function signOut(){await api('logout',{},true);localStorage.removeItem(AUTH_KEY);localStorage.removeItem(USER_KEY);currentUser=null;data=load();view='dashboard';render()}  function exportBackup(){const b=new Blob([JSON.stringify({...data,exportedAt:time()},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=`frame-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href);toast('Backup downloaded')}
  async function importBackup(e){try{let f=e.target.files[0];if(!f)return;let parsed=JSON.parse(await f.text());for(let k of Object.keys(DEFAULT))if(k!=='version'&&!Array.isArray(parsed[k]))throw Error('Backup format is not recognized');data={...structuredClone(DEFAULT),...parsed};log('Imported a studio backup');persist();syncUp('importBackup',data);toast('Backup imported')}catch(err){toast('Could not import backup: '+err.message)}e.target.value=''}
  $('#project-form').addEventListener('submit',async e=>{e.preventDefault();let f=new FormData(e.currentTarget),c=data.channels.find(x=>x.name===f.get('channel'));let p={id:id(),name:f.get('name').trim(),channelId:c?.id||'',format:f.get('format'),category:f.get('category'),language:f.get('language'),title:f.get('title').trim(),titleOptions:[f.get('title').trim(),'',''],description:f.get('description').trim(),story:'',scriptDrafts:[{id:id(),name:'Script 1',content:''}],assets:[],tasks:data.stages.map(name=>({name,done:false})),createdAt:time(),updatedAt:time(),driveFolderId:''};data.projects.unshift(p);log(`Created project ${p.name}`);$('#project-dialog').close();e.currentTarget.reset();persist();editingProject=p;view='detail';render();let r=await syncUp('createProject',p);if(r?.driveFolderId){p.driveFolderId=r.driveFolderId;editingProject=p;render()}toast(localStorage.getItem(CONFIG)?'Project created · Drive folder ready':'Project created in this browser')});
  $('#channel-form').addEventListener('submit',e=>{e.preventDefault();let f=new FormData(e.currentTarget),channel={id:f.get('id')||id(),name:f.get('name').trim(),url:f.get('url').trim(),enabled:true};let at=data.channels.findIndex(c=>c.id===channel.id);if(at>=0){channel.enabled=data.channels[at].enabled;data.channels[at]=channel;log(`Updated channel ${channel.name}`)}else{data.channels.push(channel);log(`Added channel ${channel.name}`)}$('#channel-dialog').close();persist();syncUp('saveSettings',data);toast('Channel saved')});
  $('#confirm-delete').addEventListener('click',e=>{if(!deleteTarget)return;e.preventDefault();let c=data.channels.find(x=>x.id===deleteTarget);data.channels=data.channels.filter(x=>x.id!==deleteTarget);log(`Deleted channel ${c?.name||''}`);deleteTarget=null;$('#confirm-dialog').close();persist();syncUp('saveSettings',data)});
  $$('.close-modal').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));$('#quick-channel').addEventListener('click',()=>{setView('settings');setTimeout(()=>editChannel(),10)});$('#new-project').addEventListener('click',openProjectModal);$('#export-btn').addEventListener('click',exportBackup);$('#backup-top').addEventListener('click',exportBackup);$('#menu-toggle').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');document.body.classList.toggle('menu-open',open)});$('#mobile-scrim').addEventListener('click',()=>{$('#sidebar').classList.remove('open');document.body.classList.remove('menu-open')});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#sidebar').classList.remove('open');document.body.classList.remove('menu-open')}});
  render();
  (async()=>{if(!localStorage.getItem(CONFIG))return;const token=localStorage.getItem(AUTH_KEY);if(!token){render();return}const profile=await api('getProfile',{},true);if(!profile){localStorage.removeItem(AUTH_KEY);localStorage.removeItem(USER_KEY);currentUser=null;data=load();render();return}currentUser=profile;localStorage.setItem(USER_KEY,JSON.stringify(profile));data=load();render();await syncAccountData(null)})();
})();



